changeSet.sql:
DO $$ BEGIN IF EXISTS (SELECT 1 FROM skills WHERE origin_connection_id IS NOT NULL AND connection_skill_id IS NULL) THEN RAISE EXCEPTION 'connection-skills contract: origin copy without connection_skill_id'; END IF;
IF EXISTS ( SELECT 1 FROM apps a WHERE a.deleted_at IS NULL AND a.tools IS NOT NULL AND jsonb_typeof(a.tools) = 'object' AND a.tools != '{}'::jsonb AND NOT EXISTS ( SELECT 1 FROM connection_tools ct WHERE ct.connection_id = a.id AND ct.deleted_at IS NULL ) ) THEN RAISE EXCEPTION 'connection-skills contract: live app tools have no connection_tools rows'; END IF;
IF EXISTS ( SELECT 1 FROM apps a WHERE a.deleted_at IS NULL AND a.triggers IS NOT NULL AND jsonb_typeof(a.triggers) = 'object' AND a.triggers != '{}'::jsonb AND NOT EXISTS ( SELECT 1 FROM connection_triggers ct WHERE ct.connection_id = a.id AND ct.deleted_at IS NULL ) ) THEN RAISE EXCEPTION 'connection-skills contract: live app triggers have no connection_triggers rows'; END IF; END $$;
